solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int w = in.nextInt();
        if (w <= 20) {
            System.out.println(0);
        } else {
            System.out.println((w - 20) * 15000);
        }
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int w;
    cin >> w;
    if (w <= 20) {
        cout << 0 << endl;
    } else {
        cout << (w - 20) * 15000 << endl;
    }
    return 0;
}
